Ltac vm_popcD :=
  match goal with |- context [bv_unsigned (popcDw ?w)] =>
    let v := eval vm_compute in (bv_unsigned (popcDw w)) in
    replace (bv_unsigned (popcDw w)) with v by (vm_compute; reflexivity) end.

