    Lemma loop_step : forall p A1 M1 P S B A M model R x S',
      S = x :: S' ->
      ainv MI A M model -> mstd model -> umapx MI 24 (nval24 SEGS) A1 M1 obj bl bc ents ->
      lst p M1 P S B A M R ->
      0 < p -> p + 8 * n <= alloc_ceiling -> ~ In p (map fst (live MI A0)) ->
      (forall M' R' P' B' (pc : Z),
          (pc = EXIT_PC /\ S' = [] \/ pc = LOOP_PC /\ S' <> []) ->
          lst p M1 P' S' B' A M' R' ->
          (forall a : word, ~ Wloop p (bv_unsigned a) -> M' a = M a) -> (forall a : word, M a <> None -> M' a <> None) ->
          ainv MI A M' model ->
          srealizes SEGS (cfg fx R' pc M' model) K) ->
      srealizes SEGS (cfg fx R LOOP_PC M model) K.
