Ltac scD Hrm Hba Hr Hpc' :=
          split_scs;
          first [ lazymatch goal with
                  | |- sc_denot _ _ _ (SCBr true BC_LTU (ELit 1) _) => apply Hpc'; rewrite popcD_env; evs; rewrite branch_ltu_lit_l by lia; bool_lia
                  | |- sc_denot _ _ _ (SCBr false BC_LTU (EVar 36) _) =>
