Ltac finD Hrm Hba FIN HR' Hpop :=
          eapply FIN;
          [ evs; nrm Hrm Hba; rewrite ?w_mul, ?w_add, ?v_addi_Z by lia; rewrite ?Z.add_0_r; first [reflexivity | f_equal; lia]
          | let Q := fresh in rreg HR' 2%bv Q; exact Q
          | let Q := fresh in rreg HR' 3%bv Q; exact Q
