          | let Q := fresh in rreg HR' 8%bv Q; exact Q
          | let Q := fresh in rreg HR' 9%bv Q; rewrite Q; rewrite ?w_add, ?v_addi_Z by lia; first [reflexivity | f_equal; lia]
          | let Q := fresh in rreg HR' 11%bv Q; exact Q
