          | let Q := fresh in rreg HR' 14%bv Q; rewrite Q; nrm Hrm Hba; first [reflexivity | f_equal; lia]
          | lazymatch type of HR' with regs_ok ?E' _ _ => rewrite (eq_trans (HR' 12%bv) (popcD_env E')); evs; exact Hpop end
          | let Q := fresh in rreg HR' 13%bv Q; rewrite Q; rewrite ?w_add, ?w_addm, ?v_addi_Z by lia; first [reflexivity | f_equal; lia]
          | first [ let Q := fresh in intros _; rreg HR' 16%bv Q; first [exact Q | rewrite Q; reflexivity]
                  | let Hn := fresh in intros Hn; exfalso; exact (Hn eq_refl) ]
          | first [ let Q := fresh in intros _; rreg HR' 17%bv Q; first [exact Q | rewrite Q; reflexivity]
                  | let Hn := fresh in intros Hn; exfalso; exact (Hn eq_refl) ]
          | ].
